<template>\n  <div class="projects">\n    <h1>Projekti</h1>\n    <button @click="showAddProject = true" class="btn btn-add">+ Jauns projekts</button>\n    \n    <div v-if="projects.length > 0" class="projects-grid">\n      <div v-for="project in projects" :key="project.id" class="project-card">\n        <h3>{{ project.name }}</h3>\n        <p>{{ project.description }}</p>\n        <div class="project-actions">\n          <button @click="deleteProject(project.id)" class="btn btn-delete">Dzēst</button>\n        </div>\n      </div>\n    </div>\n    \n    <div v-else class="empty-state">\n      <p>Nav projektu. Izveidojiet vienu!</p>\n    </div>\n    \n    <!-- Add Project Modal -->\n    <div v-if="showAddProject" class="modal-overlay" @click="showAddProject = false">\n      <div class="modal" @click.stop>\n        <h2>Jauns projekts</h2>\n        <form @submit.prevent="addProject">\n          <input v-model="newProject.name" type="text" placeholder="Projekta nosaukums" required>\n          <textarea v-model="newProject.description" placeholder="Apraksts"></textarea>\n          <div class="modal-actions">\n            <button type="submit" class="btn btn-primary">Izveidot</button>\n            <button type="button" @click="showAddProject = false" class="btn btn-cancel">Atcelt</button>\n          </div>\n        </form>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, onMounted } from 'vue'\nimport axios from 'axios'\n\nconst projects = ref([])\nconst showAddProject = ref(false)\nconst newProject = ref({ name: '', description: '' })\n\nonMounted(async () => {\n  await fetchProjects()\n})\n\nconst fetchProjects = async () => {\n  try {\n    const response = await axios.get('/api/projects')\n    projects.value = response.data\n  } catch (error) {\n    console.error('Failed to fetch projects:', error)\n  }\n}\n\nconst addProject = async () => {\n  try {\n    await axios.post('/api/projects', newProject.value)\n    newProject.value = { name: '', description: '' }\n    showAddProject.value = false\n    await fetchProjects()\n  } catch (error) {\n    console.error('Failed to create project:', error)\n  }\n}\n\nconst deleteProject = async (id) => {\n  if (confirm('Dzēst šo projektu?')) {\n    try {\n      await axios.delete(`/api/projects/${id}`)\n      await fetchProjects()\n    } catch (error) {\n      console.error('Failed to delete project:', error)\n    }\n  }\n}\n</script>\n\n<style scoped>\n.projects {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 30px 20px;\n  background: white;\n  min-height: 100vh;\n}\n\nh1 {\n  color: #333;\n  margin-bottom: 20px;\n}\n\n.btn-add {\n  padding: 10px 20px;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  color: white;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  margin-bottom: 30px;\n}\n\n.projects-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\n  gap: 20px;\n}\n\n.project-card {\n  background: #f8f9fa;\n  padding: 20px;\n  border-radius: 8px;\n  border: 1px solid #e0e0e0;\n}\n\n.project-card h3 {\n  color: #333;\n}\n\n.project-actions {\n  margin-top: 15px;\n}\n\n.btn-delete {\n  padding: 8px 15px;\n  background: #e74c3c;\n  color: white;\n  border: none;\n  border-radius: 4px;\n  cursor: pointer;\n}\n\n.empty-state {\n  text-align: center;\n  padding: 60px 20px;\n  color: #999;\n}\n\n.modal-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 1000;\n}\n\n.modal {\n  background: white;\n  padding: 30px;\n  border-radius: 12px;\n  max-width: 500px;\n  width: 90%;\n}\n\n.modal form {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n}\n\n.modal input,\n.modal textarea {\n  padding: 10px;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n}\n\n.modal-actions {\n  display: flex;\n  gap: 10px;\n}\n\n.btn-primary,\n.btn-cancel {\n  flex: 1;\n  padding: 10px;\n  border: none;\n  border-radius: 6px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  color: white;\n}\n\n.btn-cancel {\n  background: #ddd;\n}\n</style>\n